import React, { useState, useEffect } from 'react';
import './Dashboard.css'; // புது CSS ஃபைல்

function Dashboard() {
  const [activeTab, setActiveTab] = useState('messages');
  const [orders, setOrders] = useState([]);
  const [loginHistory, setLoginHistory] = useState([]);
  const [overallHistory, setOverallHistory] = useState([]);

  useEffect(() => {
    // எல்லா டேட்டாவையும் Python-ல் இருந்து வாங்குதல்
    fetch('http://127.0.0.1:8000/orders').then(res => res.json()).then(data => setOrders(data));
    fetch('http://127.0.0.1:8000/login-history').then(res => res.json()).then(data => setLoginHistory(data));
    fetch('http://127.0.0.1:8000/overall-history').then(res => res.json()).then(data => setOverallHistory(data));
  }, []);

  return (
    <div className="admin-layout">
      {/* Sidebar Navigation */}
      <div className="admin-sidebar">
        <h2 className="sidebar-logo">🛡️ Admin Panel</h2>
        <ul className="sidebar-menu">
          <li className={activeTab === 'messages' ? 'active' : ''} onClick={() => setActiveTab('messages')}>
            <i className="fas fa-envelope"></i> Customer Messages
          </li>
          <li className={activeTab === 'logins' ? 'active' : ''} onClick={() => setActiveTab('logins')}>
            <i className="fas fa-user-clock"></i> Login History
          </li>
          <li className={activeTab === 'history' ? 'active' : ''} onClick={() => setActiveTab('history')}>
            <i className="fas fa-history"></i> Overall History
          </li>
        </ul>
      </div>

      {/* Main Content Area */}
      <div className="admin-content">

        {/* TAB 1: MESSAGES */}
        {activeTab === 'messages' && (
          <div className="tab-section">
            <h3>Customer Messages</h3>
            <div className="table-wrapper">
              <table className="admin-table">
                <thead><tr><th>Name</th><th>Phone</th><th>Service</th><th>Message</th></tr></thead>
                <tbody>
                  {orders.length === 0 ? <tr><td colSpan="4">No messages yet.</td></tr> : 
                    orders.map((o, i) => (
                      <tr key={i}><td><strong>{o.name}</strong></td><td>{o.phone}</td><td><span className="badge">{o.service}</span></td><td>{o.message}</td></tr>
                    ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* TAB 2: LOGIN HISTORY */}
        {activeTab === 'logins' && (
          <div className="tab-section">
            <h3>User Login / Signup History</h3>
            <div className="table-wrapper">
              <table className="admin-table">
                <thead><tr><th>User / IP</th><th>Action</th><th>Time (In/Out)</th><th>Status</th></tr></thead>
                <tbody>
                  {loginHistory.map((log, i) => (
                    <tr key={i}>
                      <td>{log.user}</td>
                      <td>{log.action}</td>
                      <td>{log.time}</td>
                      <td>
                        <span className={log.status === 'Success' ? 'status-green' : 'status-red'}>
                          {log.status}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* TAB 3: OVERALL HISTORY */}
        {activeTab === 'history' && (
          <div className="tab-section">
            <h3>System & Overall History</h3>
            <div className="timeline-container">
              {overallHistory.map((hist, i) => (
                <div className="timeline-item" key={i}>
                  <div className="timeline-icon"><i className="fas fa-bolt"></i></div>
                  <div className="timeline-content">
                    <p className="timeline-time">{hist.time} - <strong>{hist.type}</strong></p>
                    <p className="timeline-event">{hist.event}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

export default Dashboard;
